<?php declare(strict_types=1);require_once dirname(__DIR__,2).'/security.php';require_once dirname(__DIR__,2).'/role_check.php';$pages=max(1,(int)ceil($total/$perPage));?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Tasks</title><link rel="stylesheet" href="/assets/style.css"><style>.task-wrap{max-width:1200px;margin:auto;padding:1rem}.table-scroll{overflow-x:auto}table{width:100%;border-collapse:collapse}th,td{padding:.7rem;border:1px solid #ccc;text-align:left}.actions{display:flex;gap:.5rem;flex-wrap:wrap}.sr-status{padding:.6rem;background:#eef}.pagination{display:flex;gap:.4rem;margin-top:1rem;flex-wrap:wrap}@media(max-width:700px){th:nth-child(3),td:nth-child(3){display:none}}</style></head><body><?php require dirname(__DIR__,2).'/nav.php';?><main class="task-wrap" id="main-content"><h1>Tasks</h1><p class="sr-status" role="status"><?= (int)$total ?> accessible task(s)</p><form method="get" action="/tasks" role="search"><label for="task-search">Search tasks</label><input id="task-search" name="search" value="<?=htmlspecialchars($search,ENT_QUOTES)?>" maxlength="100"><button type="submit">Search</button></form><?php if(\QualitySystem\Security\PermissionMatrix::allows($role,'tasks','create')):?><p><a class="btn" href="/tasks/create">Create task</a></p><?php endif;?><div class="table-scroll" tabindex="0" aria-label="Task results"><table><caption>Tasks you are authorized to access</caption><thead><tr><th scope="col">Title</th><th scope="col">Status</th><th scope="col">Program</th><th scope="col">Assigned to</th><th scope="col">Due</th><th scope="col">Actions</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><?=htmlspecialchars((string)$row['task_title'],ENT_QUOTES)?></td><td><?=htmlspecialchars((string)$row['status'],ENT_QUOTES)?></td><td><?=htmlspecialchars((string)($row['program_name']??'Unscoped'),ENT_QUOTES)?></td><td><?=htmlspecialchars((string)($row['assigned_name']??$row['responsible_person']??'Unassigned'),ENT_QUOTES)?></td><td><?=htmlspecialchars((string)($row['due_date']??''),ENT_QUOTES)?></td><td><div class="actions"><?php if(\QualitySystem\Security\PermissionMatrix::allows($role,'tasks','update')):?><a href="/tasks/<?= (int)$row['id'] ?>/edit">Edit</a><?php endif;?><?php if(\QualitySystem\Security\PermissionMatrix::allows($role,'tasks','delete')):?><form method="post" action="/tasks/<?= (int)$row['id'] ?>/delete" onsubmit="return confirm('Delete this task?')"><?=csrfField()?><button type="submit">Delete</button></form><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div><nav class="pagination" aria-label="Task result pages"><?php for($n=1;$n<=$pages&&$n<=100;$n++):?><a <?= $n===$page?'aria-current="page"':''?> href="/tasks?<?=http_build_query(['page'=>$n,'per_page'=>$perPage,'search'=>$search])?>"><?= $n ?></a><?php endfor;?></nav></main></body></html>
